import {validateParams} from './core.mjs';
const $=id=>document.getElementById(id);
import {modules} from './engineering-content.mjs';

document.querySelector('.engineering-copy .technical-note').textContent='模型图用于说明参考系统组成，不用于尺寸测量。结构、系泊与控制器固定采用官方参考配置。';
const board=document.querySelector('.engineering-board'),drawing=board.querySelector('.technical-drawing'),oldSvg=drawing.querySelector('svg');
const lineDetails=document.createElement('details');lineDetails.className='system-drawing';lineDetails.innerHTML='<summary>查看系统结构线图 <span>↘</span></summary>';lineDetails.append(oldSvg);board.after(lineDetails);
drawing.replaceChildren();drawing.innerHTML='<div class="engineering-model"><img src="./assets/oc4-studio.png" alt="银白与浅青配色的 OC4 半潜式风机模型" loading="lazy"><span class="model-view-label">OC4 / NREL 5 MW<br>参考结构视觉示意</span><span class="module-pin" id="module-pin"></span></div><div class="drawing-legend"><span>固定公开参考模型</span><span>视觉示意 · 非仿真动画</span></div>';
const tabs=document.createElement('div');tabs.className='physics-tabs';tabs.setAttribute('role','group');tabs.setAttribute('aria-label','选择工程原理模块');tabs.innerHTML=modules.map((m,i)=>`<button data-physics="${m.id}" aria-pressed="false"><span>0${i+1}</span>${m.name}</button>`).join('');board.before(tabs);
const detail=document.createElement('article');detail.className='module-detail';detail.innerHTML='<div><span class="kicker" id="module-label"></span><h2 id="module-title"></h2><p id="module-text"></p><a id="module-source" target="_blank" rel="noopener">官方模块文档 ↗</a></div><dl><div><dt>输入与耦合量</dt><dd id="module-input"></dd></div><div><dt>计算与响应</dt><dd id="module-output"></dd></div><div><dt>本项目关注通道</dt><dd id="module-watch"></dd></div></dl><p class="module-limit" id="module-limit"></p>';lineDetails.before(detail);
function selectPhysics(id){const m=modules.find(x=>x.id===id);if(!m)return;tabs.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.physics===id);b.setAttribute('aria-pressed',String(b.dataset.physics===id));});for(const [field,value] of Object.entries({label:m.english,title:m.title,text:m.text,input:m.input,output:m.output,watch:m.watch,limit:m.limit}))$('module-'+field).textContent=value;$('module-source').href=m.link;$('module-pin').textContent=m.part;drawing.dataset.physics=id;}
tabs.onclick=e=>{const b=e.target.closest('[data-physics]');if(b)selectPhysics(b.dataset.physics);};selectPhysics('hydro');
const explainer=document.querySelector('.config-explainer');explainer.querySelector('img').src='./assets/oc4-studio.png';
const summary=document.createElement('div');summary.className='draft-summary';summary.innerHTML='<span class="kicker">DRAFT / 当前配置</span><div class="draft-values"><div><span>风速</span><strong id="draft-wind"></strong></div><div><span id="draft-wave-name">波高</span><strong id="draft-wave"></strong></div><div><span id="draft-period-name">周期</span><strong id="draft-period"></strong></div></div><dl><div><dt>计算时长</dt><dd id="draft-duration"></dd></div><div><dt>分析窗口</dt><dd id="draft-window"></dd></div><div><dt>求解步长</dt><dd id="draft-dt"></dd></div></dl><p id="config-validation" role="status"></p><p class="draft-boundary">这是待提交的工况摘要。修改参数不会生成新的响应曲线；需真实运行后再分析。</p>';
explainer.querySelector('img').after(summary);
const notes=document.createElement('details');notes.className='parameter-notes';notes.innerHTML='<summary>参数怎么选？</summary><p><b>波浪：</b>规则波输入波高 H、周期 T；JONSWAP 输入显著波高 Hs、峰值周期 Tp，并保留随机种子。</p><p><b>分析起点：</b>用于排除指定时间之前的启动过程，应结合完整时序复核。</p><p><b>求解步长：</b>较小步长用于数值敏感性复核，计算通常更慢，不自动代表结果更准确。</p><p><b>模型：</b>当前固定参考水深、结构、系泊及控制器，不是任意海域设计工具。</p>';$('case-form').before(notes);
const form=$('case-form');
function draft(){return {name:$('case-name').value,wind:Number($('wind').value),wave_mode:$('wave-mode').value,wave_height:Number($('wave-height').value),wave_period:Number($('wave-period').value),duration:Number($('duration').value),discard:Number($('discard').value),seed:Number($('seed').value),solver_dt:Number($('solver-dt').value)};}
function updateSummary(){const d=draft(),irregular=d.wave_mode==='irregular';$('draft-wind').textContent=d.wind+' m/s';$('draft-wave-name').textContent=irregular?'显著波高 Hs':'波高 H';$('draft-wave').textContent=d.wave_height+' m';$('draft-period-name').textContent=irregular?'峰值周期 Tp':'周期 T';$('draft-period').textContent=d.wave_period+' s';$('draft-duration').textContent=d.duration+' s';$('draft-window').textContent=d.discard+'—'+d.duration+' s';$('draft-dt').textContent=d.solver_dt+' s';let error='';try{validateParams(d);}catch(e){error=e.message;}$('config-validation').textContent=error||'参数格式检查通过，可提交真实引擎。';$('config-validation').classList.toggle('invalid',!!error);return error;}
form.addEventListener('input',updateSummary);form.addEventListener('change',updateSummary);form.addEventListener('submit',e=>{const error=updateSummary();if(error){e.preventDefault();e.stopImmediatePropagation();$('config-validation').scrollIntoView({block:'center',behavior:'smooth'});}},true);window.addEventListener('tideflow:render',updateSummary);$('reset-config').addEventListener('click',()=>queueMicrotask(updateSummary));updateSummary();
